import fs from 'node:fs';import crypto from 'node:crypto';
import {simulateShot} from '../experiments.js';import {simulateShot as oldSimulate} from '../../shotcharge12/experiments.js';import {VERSION,SETUP,FORMULA,HOLDS,RATINGS,CHARGE,PROFILE} from '../config.js';import {physicalOutcome} from '../outcome.js';import {profileForHold,requestedCharge,speedFraction} from '../resolver.js';
const dir=new URL('../evidence/',import.meta.url),save=(n,v,pretty=true)=>fs.writeFileSync(new URL(n,dir),JSON.stringify(v,null,pretty?2:undefined)+'\n');
const payload=r=>({velocity:r.action.velocity,spin:r.action.spin,position:r.action.position,frames:r.frames,events:r.events.map(({id,metadata,...e})=>e),stats:r.stats});
const hash=r=>crypto.createHash('sha256').update(JSON.stringify(payload(r))).digest('hex');
const row=r=>{const m=r.metrics;return {id:r.id,shotPower:r.shotPower,holdMs:r.holdMs,registered:r.registered,speed:m.launchSpeed,capability:m.capabilityCeiling,speedFraction:m.launch.requestedSpeedFraction,requestedApex:m.desiredApex,angle:m.launchAngleDeg,actualApex:m.apexHeight,apexLocation:m.apexDistance,goalHeight:m.goalPlane?.height??null,landingDistance:m.firstLanding?.distance??null,result:physicalOutcome(r),physicalSha256:hash(r)};};
const runs=HOLDS.map(holdMs=>simulateShot({shotPower:80,holdMs}));for(const r of runs)r.physicalSha256=hash(r);
save('review.json',{version:VERSION,setup:SETUP,formula:FORMULA,runs},false);
const verificationHolds=[0,20,40,80,100,150,173,200,225,300,425,450,550,700,800],verificationRows=RATINGS.flatMap(shotPower=>verificationHolds.map(holdMs=>row(simulateShot({shotPower,holdMs}))));
function threshold(fn,target){let lo=40,hi=450;for(let i=0;i<50;i++){const mid=(lo+hi)/2;if(fn(mid)<target)lo=mid;else hi=mid;}return (lo+hi)/2;}
const milestones=[.5,.7,1,1.4,1.5,2,2.4,2.9].map(apex=>{const h=threshold(h=>profileForHold(h).desiredApex,apex);let lo=80,hi=600;for(let i=0;i<50;i++){const m=(lo+hi)/2,q=(m-80)/520,a=.32+2.68*q**3*(4-3*q);if(a<apex)lo=m;else hi=m;}return {apex,newHoldMs:h,oldHoldMs:(lo+hi)/2,newSpeedFraction:speedFraction(requestedCharge(h).q)};});
const highSpeedHold=threshold(h=>speedFraction(requestedCharge(h).q),.8);
const comparisons=[100,150,200,300,450].map(holdMs=>({holdMs,old:row(oldSimulate({shotPower:80,holdMs})),current:verificationRows.find(r=>r.shotPower===80&&r.holdMs===holdMs)}));
save('measurements.json',{version:VERSION,formula:FORMULA,charge:CHARGE,trajectory:PROFILE,rows:runs.map(row),verificationRows,milestones,comparisons,highSpeedLowShot:{operationalDefinition:'High speed means at least 80% of the player ceiling; ultra-low means first-flight centre apex ≤ 0.70 m. These are observer definitions, never physics inputs.',firstHighSpeedHoldMs:highSpeedHold,apexAtHighSpeedThreshold:profileForHold(highSpeedHold).desiredApex,ultraLowWindowEndsMs:milestones.find(r=>r.apex===.7).newHoldMs,overlap:false},definitions:{heights:'Ball-centre height above turf, metres. First-flight apex sampled at native 240 Hz.',apexLocation:'Forward distance from [86,0.11,34] at the physical first-flight apex.',goalPlane:'Contact-aware crossing at x=105, 19 m ahead; reference geometry only, no goal/keeper colliders.',landingDistance:'Forward distance to first physical turf contact; observed, never targeted.',oldMaximum:'600 ms',newMaximum:'450 ms (provisional)',anchorConstraint:'The preserved 3.0 m maximum-useful profile already clears the bar in this fixed 19 m setup.'}});
console.log(JSON.stringify({mainCases:runs.length,verificationCases:verificationRows.length,milestones,highSpeedHold,apexAtHighSpeed:profileForHold(highSpeedHold).desiredApex},null,2));

