import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
import {simulateShot} from '../experiments.js';import {simulateShot as oldSimulate} from '../../shotcharge12/experiments.js';import {requestedCharge,speedFraction,profileForHold,resolveShot} from '../resolver.js';import {RATINGS,CHARGE,PROFILE,OVERCHARGE} from '../config.js';import {attachInput} from '../input.js';import {physicalOutcome} from '../outcome.js';
const root=fileURLToPath(new URL('..',import.meta.url)),repo=path.resolve(root,'../../..'),workspace=path.resolve(repo,'../..'),checks=[];
const payload=r=>({velocity:r.action.velocity,spin:r.action.spin,position:r.action.position,frames:r.frames,events:r.events.map(({id,metadata,...e})=>e),stats:r.stats});
const hash=x=>crypto.createHash('sha256').update(typeof x==='string'||Buffer.isBuffer(x)?x:JSON.stringify(x)).digest('hex');
const close=(a,b,tol=1e-7)=>assert.ok(Math.abs(a-b)<=tol,`${a} != ${b} ± ${tol}`),test=(name,fn)=>{fn();checks.push({name,status:'PASS'});console.log('PASS '+name);};
const runs=JSON.parse(fs.readFileSync(path.join(root,'evidence/review.json'))).runs,data=JSON.parse(fs.readFileSync(path.join(root,'evidence/measurements.json')));
test('Every nonnegative tap, including timer-resolution zero, registers; old 80 ms floor preserved exactly through 40 ms',()=>{for(const shotPower of RATINGS){const old=oldSimulate({shotPower,holdMs:80});for(const holdMs of [0,.001,1,5,13.3,20,39.999,40]){const r=simulateShot({shotPower,holdMs});assert.equal(r.registered,true);assert.equal(r.metrics.launch.holdMs,holdMs);assert.equal(r.metrics.launch.requestedSpeedFraction,.4);assert.deepEqual(payload(r),payload(old));}}for(const holdMs of [-1,NaN,Infinity])assert.throws(()=>requestedCharge(holdMs));});
test('450 ms maximum is physically identical to old 600 ms at all five ratings; speed ceilings preserved',()=>{for(const shotPower of RATINGS){assert.deepEqual(payload(simulateShot({shotPower,holdMs:450})),payload(oldSimulate({shotPower,holdMs:600})));for(const holdMs of [450,500,550,700,800,1e9]){const r=simulateShot({shotPower,holdMs});assert.equal(r.metrics.launchSpeed,r.metrics.capabilityCeiling);close(Math.hypot(...r.action.velocity),r.metrics.capabilityCeiling,1e-12);}}});
test('Existing speed-curve shape and overcharge shape preserved under the new time mapping',()=>{for(const h of [0,20,40,100,173,200,300,425,450]){const q=requestedCharge(h).q,oldHold=80+520*q;for(const shotPower of RATINGS){const r=simulateShot({shotPower,holdMs:h}),old=oldSimulate({shotPower,holdMs:oldHold});close(r.metrics.launchSpeed,old.metrics.launchSpeed,1e-12);}}for(const shotPower of RATINGS)for(const extra of [50,100,150,250,350,550])assert.deepEqual(payload(simulateShot({shotPower,holdMs:450+extra})),payload(oldSimulate({shotPower,holdMs:600+extra})));});
test('Continuous, monotonic, nonlinear timing; exact off-grid duration is retained',()=>{let previousSpeed=.4,previousApex=.32;for(let h=0;h<=2000;h+=.5){const q=requestedCharge(h).q,f=speedFraction(q),a=profileForHold(h).desiredApex;assert.ok(f>=previousSpeed-1e-14&&a>=previousApex-1e-14&&f<=1&&a<=10);previousSpeed=f;previousApex=a;}for(const boundary of [40,450]){const e=.001;assert.ok(Math.abs(profileForHold(boundary-e).desiredApex-profileForHold(boundary+e).desiredApex)<1e-6);assert.ok(Math.abs(speedFraction(requestedCharge(boundary-e).q)-speedFraction(requestedCharge(boundary+e).q))<.000003);}const r=simulateShot({shotPower:80,holdMs:173.123456});assert.equal(r.metrics.launch.holdMs,173.123456);assert.notEqual(r.metrics.desiredApex,profileForHold(173).desiredApex);});
test('Trajectory brackets match the requested faster low→normal→rising distribution',()=>{for(const [h,lo,hi] of [[100,.5,.7],[150,.9,1.2],[200,1.4,1.7],[225,1.4,1.75],[300,2.1,2.4],[450,3,3]]){const a=profileForHold(h).desiredApex;assert.ok(a>=lo&&a<=hi);}for(const m of data.milestones)assert.ok(m.newHoldMs<m.oldHoldMs);assert.ok(data.highSpeedLowShot.apexAtHighSpeedThreshold>1.6);assert.ok(data.highSpeedLowShot.ultraLowWindowEndsMs<data.highSpeedLowShot.firstHighSpeedHoldMs);});
test('75 supporting scenarios maintain shared apex across SP and retain varied pace',()=>{assert.equal(data.verificationRows.length,75);for(const row of data.verificationRows){assert.ok(row.registered);close(row.actualApex,row.requestedApex,1e-6);assert.ok(row.speed<=row.capability);}for(const holdMs of [...new Set(data.verificationRows.map(r=>r.holdMs))]){const rs=data.verificationRows.filter(r=>r.holdMs===holdMs);assert.equal(new Set(rs.map(r=>r.requestedApex)).size,1);assert.equal(new Set(rs.map(r=>r.speed)).size,5);}});
test('All progression shots repeat deterministically; single launch and stable forward physical flight',()=>{for(const r of runs){const again=simulateShot({shotPower:r.shotPower,holdMs:r.holdMs});assert.equal(hash(payload(r)),hash(payload(again)));assert.equal(r.metrics.launchCount,1);assert.deepEqual(r.action.spin,[0,0,-4]);assert.equal(r.action.velocity[2],0);assert.ok(!r.metrics.range.stopping.censored);for(const f of r.frames){assert.ok([...f.p,...f.v,...f.w].every(Number.isFinite));if(f.time>0&&f.time<=r.metrics.firstLanding.time)assert.ok(f.v[0]>0);}}for(const shotPower of RATINGS)for(const holdMs of [0,5,173.123456,450.001,800]){const a=simulateShot({shotPower,holdMs}),b=simulateShot({shotPower,holdMs});assert.equal(hash(payload(a)),hash(payload(b)));}});
test('Actual input controller forwards sub-millisecond/quick holds without a debounce; ignores repeats, cancels safely',()=>{const keyboard=new EventTarget(),pointer=new EventTarget(),cancelTarget=new EventTarget();let clock=100;const received=[];const input=attachInput({keyboard,pointer,cancelTarget,now:()=>clock,onRelease:r=>received.push(r)});const emit=(target,name,props={})=>{const e=new Event(name,{cancelable:true});Object.assign(e,props);target.dispatchEvent(e);};for(const kind of ['keyboard','pointer'])for(const duration of [0,.001,1,5,20,40,173.123456]){const start=clock;if(kind==='keyboard')emit(keyboard,'keydown',{code:'Space'});else emit(pointer,'pointerdown',{button:0,pointerId:3});clock+=duration;if(kind==='keyboard')emit(keyboard,'keyup',{code:'Space'});else emit(pointer,'pointerup',{pointerId:3});assert.equal(received.at(-1).holdMs,clock-start);assert.equal(requestedCharge(received.at(-1).holdMs).registered,true);clock+=10;}const n=received.length;emit(keyboard,'keydown',{code:'Space'});emit(keyboard,'keydown',{code:'Space',repeat:true});emit(cancelTarget,'blur');emit(keyboard,'keyup',{code:'Space'});assert.equal(received.length,n);input.destroy();});
